def unanimous_kill_rate(group, kills):
    present = [r for r in group if r["seq_id"] in kills]
    if not present:
        return 0.0, 0, 0
    n_unanimous = sum(
        1 for r in present
        if UNANIMOUS_BATTERY.issubset(kills[r["seq_id"]])
    )
    return n_unanimous / len(present), n_unanimous, len(present)


